/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Internal
 *   Functions: run, timeline, steps, candy, bible, candyPlan, titleSteps, fetched, request, bridgeQuery, stage,
 *              begin, rows, alias
 *   Constants: started, stepped, plannedTitles
 * Tests
 *   - a review view's timeline lists its title searches with the review's own texts, its Track-title searches, release details, the iTunes fallback, its bridge and the alias lookups, each with its state and counts
 *   - a review view's timeline shows a search text only when it is the review's own title, Artist name, Track title or submitted name, and a bridge title only when a shown candidate carries it
 *   - a review view's timeline says why no Track title was searched, else whether they were sent, not needed or not yet decided
 *   - a search the record cannot vouch was sent reads as unconfirmed: past the candidate bound, after MusicBrainz's retries ran out, and Track titles the run may have stopped short of
 *   - in a plan without Track-title searches, a search the candidate bound kept unsent is skipped, and never done once MusicBrainz's retries run out after the searches
 *   - a bridge search names its title only once answered: one left unsent when MusicBrainz's retries ran out checked nothing
 *   - a retrying review run shows when it retries, for which source and which retry of how many; any other run, an unreadable time or an attempt out of bounds shows none
 *   - a timeline's times are the run's start, last step and end within the years 0000-9999; an unreadable start or last-step time, a run that planned no search or a view not built for the lookup read leaves the key out, and an import view never carries it
 *   - a review candidate's subset comparison shows how its pairing was made single only when stored on a single pairing; unknown values and other pairings show none, and the import view never carries it
 *   - the timeline stays within its bounds: at most six title searches, four texts a step, counts within 100 and twelve steps
 * @end-catalog */

/**
 * An existing-Album review run's timeline as its lookup view shows it, without a database: the steps and their states and counts,
 * the searches the record cannot vouch were sent (driven through the run's own steps), the searched texts the view admits (only
 * the review's own saved values and a submitted name), the Track-title search state, the automatic retry, the run's times and the
 * bounds. Identifiers and accounts are synthetic; the titles and Artist names of two
 * catalog Albums (a live recording with numbered romanized titles, and a best-of without durations), whose lookups prompted the
 * timeline, are kept as fixture literals, and every other name is synthetic.
 */
import assert from 'node:assert/strict';
import { test } from 'node:test';
// The database module loads first; importing adminImportService before it trips the index import cycle.
import '../../src/infrastructure/database';
import type { AdminImportDocument } from '../../src/administration/import/adminImportService';
import { planCatalogReviewLookup } from '../../src/administration/lookup/lookupReviewEvidence';
import { proceedLookupRun } from '../../src/administration/lookup/lookupRunStep';
import { rankLookupWithinBudget, startLookupRun, type MetadataLookupRecord, type StoredLookupCandidate } from '../../src/administration/lookup/metadataLookupRecord';
import { catalogReviewLookupView, importLookupView } from '../../src/administration/lookup/lookupView';
import { reviewActor, reviewLookupDocument, storedCandidate, syntheticMbid, syntheticRelease } from '../support/catalogReviewLookupFixtures';

const started = new Date('2026-10-22T01:24:52.631Z'), stepped = new Date('2026-10-22T01:25:14.027Z');
/** A review's stored run: complete with no query or candidate unless `extra` says otherwise. */
const run = (doc: AdminImportDocument, extra: Record<string, unknown> = {}): MetadataLookupRecord => ({
    _id: doc._id, run: 3, state: 'complete', issue: null, outcome: 'candidates', operationId: syntheticMbid(600), actorId: reviewActor, grantSource: 'submit',
    grantExpiresAt: new Date(stepped.getTime() + 600_000), automatic: false, input: { trigger: 'catalog', submitted: null }, queries: [], queryIndex: 0, phase: 'done',
    fileSetDigest: 'f'.repeat(64), files: [], attempts: { musicbrainz: 0 }, retryAt: null, candidates: [], ranking: null, searchComplete: true, exactSearchComplete: true,
    applied: null, staleSlotIds: [], automaticRuns: 1, folderUsed: false, leaseOwner: null, leaseUntil: null, createdAt: started, updatedAt: stepped, completedAt: stepped, ...extra
}) as unknown as MetadataLookupRecord;
const timeline = (doc: AdminImportDocument, extra: Record<string, unknown> = {}) => catalogReviewLookupView(run(doc, extra), doc, { timeline: true })!.timeline;
/** Each step as [kind, state, done/total or '', texts as `text · artist`]. */
const steps = (doc: AdminImportDocument, extra: Record<string, unknown> = {}) => timeline(doc, extra)!.steps.map(step =>
    [step.kind, step.state, step.total === undefined ? '' : `${step.done}/${step.total}`, (step.texts ?? []).map(text => [text.text, text.artist].filter(Boolean).join(' · '))]);

/** CANDY LIVE 2's shape: a decorated primary Artist name and two members whose titles and filenames start with their positions. */
const candy = () => reviewLookupDocument({ title: 'CANDY LIVE 2', primaryNames: ['ヰ世界情緒 -Isekaijoucho-'], members: [
    { durationMs: 215_659, title: '1-01 Yorugaonokokuhaku(Live)', originalFileName: '1-01 Yorugaonokokuhaku(Live).wav' },
    { durationMs: 382_752, title: '1-02 Unknown Mother Goose(Live)', originalFileName: '1-02 Unknown Mother Goose(Live).wav' }] });
/** The best-of's shape: no durations, titles numbered "1.01."; its Track titles are searched by name. */
const bible = () => reviewLookupDocument({ title: '雪の華15周年記念ベスト盤 BIBLE／中島美嘉', primaryNames: ['中島美嘉'], members: [{ durationMs: null, title: '1.01.雪の華' },
    { durationMs: null, title: '1.02.Synthetic B' }] });
const candyPlan = (doc: AdminImportDocument) => planCatalogReviewLookup(doc, { submitted: { kind: 'album', text: 'CANDY LIVE 2' } });
const titleSteps = (state: string) => [['albumArtist', state, '', ['CANDY LIVE 2 · ヰ世界情緒']], ['album', state, '', ['CANDY LIVE 2']],
    ['albumArtist', state, '', ['CANDY LIVE 2 · ヰ世界情緒 -Isekaijoucho-']]];
const plannedTitles = ['Unknown Mother Goose · ヰ世界情緒', 'Yorugaonokokuhaku · ヰ世界情緒'];
const fetched = (index: number, title: string) => storedCandidate(syntheticRelease(syntheticMbid(index), [{ tracks: [{ lengthMs: 215_640 }, { lengthMs: 382_746 }] }], { title }));
const request = (storefront: string) => ({ kind: 'itunesSearch', term: 'CANDY LIVE 2 ヰ世界情緒 -Isekaijoucho-', entity: 'album', storefront });
const bridgeQuery = (release: string, artist = 'ヰ世界情緒 -Isekaijoucho-') => ({ kind: 'musicBrainzReleaseSearch', query: { release, artist }, basis: 'albumText', itemKeys: ['collection:1'] });
const stage = (extra: Record<string, unknown> = {}) => ({ reason: 'noMatch', text: 'candy live 2', requests: [request('jp'), request('us')], requestIndex: 2, items: [],
    bridge: [bridgeQuery('創生'), bridgeQuery('色彩'), bridgeQuery('V.W.P'), bridgeQuery('創生 Deluxe')], bridgeIndex: 4, bridgeOutcomes: ['found', 'none', 'none', 'found'],
    state: 'answered', complete: false, finalized: true, ...extra });
/** A review's run as it starts, from the review's own plan, and each step after it from the run's own step function. */
function begin(doc: AdminImportDocument) {
    const { input, plan } = planCatalogReviewLookup(doc);
    const started = startLookupRun(null, { importId: doc._id, actorId: reviewActor, grantSource: 'create', operationId: syntheticMbid(601), automatic: true, input, queries: plan.queries,
        fileSet: { files: [], digest: 'f'.repeat(64) }, now: stepped, comparison: 'subset' });
    return proceedLookupRun({ ...started, state: 'running' }, doc, null, stepped);
}
/** Each step of a run's timeline as [kind, state, texts as `text · artist`]. */
const rows = (record: MetadataLookupRecord, doc: AdminImportDocument) => catalogReviewLookupView(record, doc, { timeline: true })!.timeline!.steps.map(step =>
    [step.kind, step.state, (step.texts ?? []).map(text => [text.text, text.artist].filter(Boolean).join(' · '))]);
const alias = (index: number, state = 'fetched') => ({ kind: 'artist', id: syntheticMbid(30 + index), state, names: [] });

test('a review view\'s timeline lists its title searches with the review\'s own texts, its Track-title searches, release details, the iTunes fallback, its bridge and the alias lookups, each with its state and counts', () => {
    const doc = candy(), { input, plan } = candyPlan(doc), planned = { input, queries: plan.queries };
    // Queued: every step waits, the undecided Track-title searches as planned.
    assert.deepEqual(steps(doc, { ...planned, state: 'queued', phase: 'search', outcome: null, completedAt: null }), [...titleSteps('pending'),
        ['trackTitle', 'pending', '', plannedTitles], ['details', 'pending', '', []], ['itunes', 'pending', '', []], ['bridge', 'pending', '', []], ['aliases', 'pending', '', []]]);
    // Running its second search: the first was sent, the third waits.
    assert.deepEqual(steps(doc, { ...planned, state: 'running', phase: 'search', queryIndex: 1, outcome: null, completedAt: null }).slice(0, 4),
        [titleSteps('done')[0], titleSteps('active')[1], titleSteps('pending')[2], ['trackTitle', 'pending', '', plannedTitles]]);
    // Retrying while it reads release details: one of two settled, the details step active.
    const details = steps(doc, { ...planned, state: 'retrying', issue: 'sourceBusy', phase: 'details', queryIndex: 3, retryAt: new Date('2026-10-22T01:26:10Z'),
        attempts: { musicbrainz: 2 }, candidates: [{ ...fetched(1, 'CANDY LIVE 2'), release: null, details: 'pending' }, fetched(2, 'CANDY LIVE 2')], outcome: null, completedAt: null });
    assert.deepEqual(details.slice(3, 5), [['trackTitle', 'pending', '', plannedTitles], ['details', 'active', '1/2', []]]);
    // Completed with the iTunes fallback: its requests, its bridge (texts only where a shown candidate carries the title) and aliases.
    const found = [fetched(1, 'CANDY LIVE 2'), fetched(2, 'CANDY LIVE 2'), fetched(3, '創生'), fetched(4, '色彩')];
    assert.deepEqual(steps(doc, { ...planned, queryIndex: 5, trackTitleSearch: 'sent', creditFound: true, candidates: found, itunesStage: stage(),
        aliases: [alias(0), alias(1), alias(2, 'failed'), alias(3, 'missing')] }), [...titleSteps('done'), ['trackTitle', 'done', '', plannedTitles], ['details', 'done', '4/4', []],
        ['itunes', 'done', '2/2', []], ['bridge', 'done', '4/4', ['創生', '色彩']], ['aliases', 'done', '4/4', []]]);
    // Completed without it: the fallback was not needed and has no bridge; a run without candidates or alias targets skips both.
    assert.deepEqual(steps(doc, { ...planned, queryIndex: 5, trackTitleSearch: 'skipped', outcome: 'noRelease' }).slice(3),
        [['trackTitle', 'skipped', '', []], ['details', 'skipped', '', []], ['itunes', 'skipped', '', []], ['aliases', 'skipped', '', []]]);
    // Stopped during the searches: the searches it never reached and every later step are still pending; nothing is skipped.
    assert.deepEqual(steps(doc, { ...planned, state: 'stopped', issue: 'grantExpired', phase: 'search', queryIndex: 1, outcome: null }).map(step => step[1]),
        ['done', 'pending', 'pending', 'pending', 'pending', 'pending', 'pending', 'pending']);
    // A search the candidate bound kept unsent after the search phase is skipped; a stage's unavailable iTunes request has no counts.
    const titlesOnly = { input, queries: plan.queries.slice(0, 3) };
    assert.deepEqual(steps(doc, { ...titlesOnly, state: 'running', phase: 'aliases', queryIndex: 2, candidates: found, itunesStage: stage({ state: 'unavailable', bridge: [] }),
        aliases: [alias(0), alias(1, 'pending')], outcome: null, completedAt: null }), [titleSteps('done')[0], titleSteps('done')[1], titleSteps('skipped')[2],
        ['details', 'done', '4/4', []], ['itunes', 'skipped', '', []], ['bridge', 'skipped', '', []], ['aliases', 'active', '1/2', []]]);
});

test('a review view\'s timeline shows a search text only when it is the review\'s own title, Artist name, Track title or submitted name, and a bridge title only when a shown candidate carries it', () => {
    // The default members keep their default filenames (synthetic-1.flac) and the manifest's root is a folder name.
    const doc = reviewLookupDocument({ members: [{ durationMs: 210_000 }, { durationMs: 220_000 }] });
    const search = (query: Record<string, unknown>, basis = 'albumText', extra: Record<string, unknown> = {}) => ({ kind: 'musicBrainzReleaseSearch', query, basis, ...extra });
    const queries = [search({ release: 'synthetic-1.flac' }), search({ release: 'Synthetic Album', artist: 'Synthetic Stranger' }), search({ barcode: '4006381333931' }, 'barcode'),
        search({ catno: 'SYN-001' }, 'catalogNumber'), search({ release: 'Synthetic Folder' }, 'folder'), { kind: 'musicBrainzRelease', releaseId: syntheticMbid(7), basis: 'releaseId' },
        search({ release: 'Synthetic Album Respelled' }, 'albumText', { fallback: true }), search({ release: 'Synthetic Album', artist: 'Synthetic Ensemble' })];
    const shown = timeline(doc, { queries, queryIndex: 8, candidates: [fetched(1, 'Synthetic Album')],
        itunesStage: stage({ requests: [{ ...request('jp'), term: 'Synthetic Secret Term' }], requestIndex: 1, bridge: [bridgeQuery('Synthetic Elsewhere', 'Synthetic iTunes Artist')], bridgeIndex: 1 }) })!;
    // The filename and the unknown Artist keep their step without a text; identifier, folder and fallback searches are never listed.
    assert.deepEqual(shown.steps.map(step => [step.kind, step.texts ?? null]), [['album', null], ['albumArtist', null], ['albumArtist', [{ text: 'Synthetic Album', artist: 'Synthetic Ensemble' }]],
        ['details', null], ['itunes', null], ['bridge', null], ['aliases', null]]);
    const text = JSON.stringify(shown);
    for (const hidden of ['synthetic-1.flac', '4006381333931', 'SYN-001', 'Synthetic Folder', 'Respelled', 'Synthetic Stranger', 'Synthetic Secret Term', 'Synthetic Elsewhere',
        'Synthetic iTunes Artist', syntheticMbid(7)]) assert.equal(text.includes(hidden), false, hidden);
    // A submitted name and Artist name are the run's own texts, compared in their NFKC and whitespace form.
    const submitted = timeline(doc, { input: { trigger: 'submitted', submitted: { kind: 'song', text: 'Synthetic  Typed Song', artist: 'Synthetic Typed Artist' } },
        queries: [{ kind: 'musicBrainzRecordingSearch', query: { recording: 'Synthetic Typed Song', artist: 'Synthetic Typed Artist' }, basis: 'songText' },
            { kind: 'musicBrainzRecordingSearch', query: { recording: 'Ｓｙｎｔｈｅｔｉｃ Typed Song' }, basis: 'songText' }], queryIndex: 2 })!;
    assert.deepEqual(submitted.steps.slice(0, 2), [{ kind: 'songArtist', state: 'done', texts: [{ text: 'Synthetic Typed Song', artist: 'Synthetic Typed Artist' }] },
        { kind: 'song', state: 'done', texts: [{ text: 'Ｓｙｎｔｈｅｔｉｃ Typed Song' }] }]);
});

test('a review view\'s timeline says why no Track title was searched, else whether they were sent, not needed or not yet decided', () => {
    const doc = candy(), { input, plan } = candyPlan(doc), planned = { input, queries: plan.queries, queryIndex: 5 };
    const decided = (extra: Record<string, unknown>) => { const shown = timeline(doc, { ...planned, ...extra })!; return [shown.trackTitleSearch, shown.steps.find(step => step.kind === 'trackTitle')]; };
    assert.deepEqual(decided({ trackTitleSearch: 'sent', creditFound: true }), [{ state: 'sent' }, { kind: 'trackTitle', state: 'done',
        texts: [{ text: 'Unknown Mother Goose', artist: 'ヰ世界情緒' }, { text: 'Yorugaonokokuhaku', artist: 'ヰ世界情緒' }] }]);
    assert.deepEqual(decided({ trackTitleSearch: 'skipped' }), [{ state: 'notNeeded' }, { kind: 'trackTitle', state: 'skipped' }]);
    assert.deepEqual(decided({ state: 'unavailable', issue: 'sourceBusy', trackTitleSearch: 'skipped', exhausted: { musicbrainz: 'sourceBusy' } }),
        [{ state: 'skipped', reason: 'unavailable' }, { kind: 'trackTitle', state: 'skipped' }]);
    assert.deepEqual(decided({ state: 'running', phase: 'details', queryIndex: 3 }), [{ state: 'pending' }, { kind: 'trackTitle', state: 'pending',
        texts: [{ text: 'Unknown Mother Goose', artist: 'ヰ世界情緒' }, { text: 'Yorugaonokokuhaku', artist: 'ヰ世界情緒' }] }]);
    // While they are being sent the step is active.
    assert.equal(decided({ state: 'running', phase: 'search', queryIndex: 4, trackTitleSearch: 'sent' })[1]!.state, 'active');
    // Sent after the credited title searches returned no release: alone, and a title too light to search alone is left out.
    const light = reviewLookupDocument({ primaryNames: ['Synthetic Lead'], members: [{ durationMs: 1, title: 'Synthetic Heavy Title' }, { durationMs: 2, title: 'Rainy' }] });
    const lightPlan = planCatalogReviewLookup(light);
    assert.deepEqual(lightPlan.plan.queries.filter(query => query.basis === 'trackTitle').map(query => (query as { query: unknown }).query),
        [{ recording: 'Synthetic Heavy Title', artist: 'Synthetic Lead' }, { recording: 'Rainy', artist: 'Synthetic Lead' }]);
    assert.deepEqual(timeline(light, { input: lightPlan.input, queries: lightPlan.plan.queries, queryIndex: 4, trackTitleSearch: 'sent' })!.steps.find(step => step.kind === 'trackTitle'),
        { kind: 'trackTitle', state: 'done', texts: [{ text: 'Synthetic Heavy Title' }] });
    // The stored CANDY run, planned before numbered titles were searched by name: no Track-title row, as this release cannot say why.
    const stored = timeline(doc, { input, queries: plan.queries.slice(0, 2), queryIndex: 2, trackTitleSearch: null, creditFound: null })!;
    assert.deepEqual(['trackTitleSearch' in stored, stored.steps.some(step => step.kind === 'trackTitle')], [false, false]);
    // The best-of's Track titles are searched by name.
    const snow = bible(), snowPlan = planCatalogReviewLookup(snow);
    assert.deepEqual(steps(snow, { input: snowPlan.input, queries: snowPlan.plan.queries, queryIndex: 4, trackTitleSearch: 'sent', creditFound: true }).slice(0, 3),
        [['albumArtist', 'done', '', ['雪の華15周年記念ベスト盤 BIBLE · 中島美嘉']], ['album', 'done', '', ['雪の華15周年記念ベスト盤 BIBLE']], ['trackTitle', 'done', '', ['Synthetic B · 中島美嘉', '雪の華 · 中島美嘉']]]);
    // Why none was planned: the picker's reason when every skipped member shares it, else none distinctive.
    const skipped = (members: { title: string; originalFileName?: string | null }[], options: { albumEntries?: [] } = {}) => {
        const album = reviewLookupDocument({ members: members.map(member => ({ durationMs: 1, ...member })), ...options });
        const { input: catalog, plan: titles } = planCatalogReviewLookup(album);
        assert.equal(titles.queries.some(query => query.basis === 'trackTitle'), false);
        const shown = timeline(album, { input: catalog, queries: titles.queries, queryIndex: titles.queries.length })!;
        return [shown.trackTitleSearch, shown.steps.find(step => step.kind === 'trackTitle')?.state];
    };
    assert.deepEqual(skipped([{ title: '01.Synthetic One' }, { title: '03.Synthetic Three' }, { title: '02.Synthetic Two' }]), [{ state: 'skipped', reason: 'positionsStart' }, 'skipped']);
    assert.deepEqual(skipped([{ title: 'Synthetic Song A', originalFileName: 'Synthetic Song A.flac' }, { title: 'synthetic_song_b' }]), [{ state: 'skipped', reason: 'fileName' }, 'skipped']);
    assert.deepEqual(skipped([{ title: 'Intro' }, { title: 'Interlude 2' }, { title: 'Outro' }]), [{ state: 'skipped', reason: 'generic' }, 'skipped']);
    assert.deepEqual(skipped([{ title: 'Rain' }, { title: 'Snow' }], { albumEntries: [] }), [{ state: 'skipped', reason: 'noneDistinct' }, 'skipped']);
    // An Album without members has no Track titles to search: no key and no row.
    const empty = reviewLookupDocument(), emptyPlan = planCatalogReviewLookup(empty);
    const none = timeline(empty, { input: emptyPlan.input, queries: emptyPlan.plan.queries, queryIndex: emptyPlan.plan.queries.length })!;
    assert.deepEqual(['trackTitleSearch' in none, none.steps.some(step => step.kind === 'trackTitle')], [false, false]);
});

test('a search the record cannot vouch was sent reads as unconfirmed: past the candidate bound, after MusicBrainz\'s retries ran out, and Track titles the run may have stopped short of', () => {
    // The best-of's first credited search returns 16 releases: at the bound of 15 its search by the name alone is never sent, yet
    // `queryIndex` moves past it to the Track titles, so only the first search is certain.
    const doc = bible(), first = begin(doc);
    const found = Array.from({ length: 16 }, (_entry, index) => ({ releaseId: syntheticMbid(100 + index), trackCount: 2 }));
    const bound = proceedLookupRun(first.next, doc, { kind: 'found', action: first.step.action!, found, complete: false } as never, stepped).next;
    assert.deepEqual([bound.phase, bound.queryIndex, bound.candidates.length], ['details', 2, 15]);
    const searched = ['雪の華15周年記念ベスト盤 BIBLE · 中島美嘉'], alone = ['雪の華15周年記念ベスト盤 BIBLE'];
    assert.deepEqual(rows(bound, doc).slice(0, 3), [['albumArtist', 'done', searched], ['album', 'unconfirmed', alone], ['trackTitle', 'pending', ['Synthetic B · 中島美嘉', '雪の華 · 中島美嘉']]]);
    // Once its Track titles went out, only the first is certain: the bound or a partial search may have stopped the second.
    const sent = { ...bound, state: 'complete', phase: 'done', trackTitleSearch: 'sent', creditFound: true, queryIndex: bound.queries.length, completedAt: stepped } as MetadataLookupRecord;
    assert.deepEqual(rows(sent, doc).slice(0, 4), [['albumArtist', 'done', searched], ['album', 'unconfirmed', alone], ['trackTitle', 'done', ['Synthetic B · 中島美嘉']],
        ['trackTitle', 'unconfirmed', ['雪の華 · 中島美嘉']]]);
    // CANDY LIVE 2's first search fails until MusicBrainz's retries run out and the iTunes fallback starts: no title search is
    // certain, the failed one included, and its Track titles were not sent; a run that completes from iTunes keeps them so.
    const live = candy();
    let record = begin(live).next;
    for (let attempt = 1; attempt <= 4; attempt++) {
        const at = new Date(stepped.getTime() + attempt * 1_000);
        record = proceedLookupRun(record, live, { kind: 'failed', source: 'musicbrainz', failure: 'unavailable', retryAfterMs: null } as never, at).next;
        if (record.state === 'retrying') record = proceedLookupRun({ ...record, state: 'running' }, live, null, at).next;
    }
    assert.deepEqual([record.state, record.phase, record.queryIndex], ['running', 'itunes', 5]);
    const exhausted = [['albumArtist', 'unconfirmed', ['CANDY LIVE 2 · ヰ世界情緒']], ['album', 'unconfirmed', ['CANDY LIVE 2']],
        ['albumArtist', 'unconfirmed', ['CANDY LIVE 2 · ヰ世界情緒 -Isekaijoucho-']], ['trackTitle', 'skipped', []]];
    assert.deepEqual(rows(record, live).slice(0, 4), exhausted);
    assert.deepEqual(rows({ ...record, state: 'complete', phase: 'done', issue: 'sourceUnavailable', completedAt: stepped } as MetadataLookupRecord, live).slice(0, 4), exhausted);
    // The same plan with every search answered, its candidates few and complete: everything it sent is done.
    const { input, plan } = planCatalogReviewLookup(live), planned = { input, queries: plan.queries, trackTitleSearch: 'sent', creditFound: true };
    const titles = (extra: Record<string, unknown>) => steps(live, { ...planned, ...extra }).filter(step => step[0] === 'trackTitle').map(step => [step[1], step[3]]);
    const both = ['Unknown Mother Goose · ヰ世界情緒', 'Yorugaonokokuhaku · ヰ世界情緒'];
    assert.deepEqual(titles({ queryIndex: 5 }), [['done', both]]);
    // At 25 candidates the later Track titles may not have gone out.
    assert.deepEqual(titles({ queryIndex: 5, candidates: Array.from({ length: 25 }, (_entry, index) => fetched(200 + index, 'CANDY LIVE 2')) }), [['done', both.slice(0, 1)], ['unconfirmed', both.slice(1)]]);
    // A run that ended while it sent them sent those before `queryIndex`; the one at it may or may not have gone out.
    const ended = { state: 'stopped', issue: 'grantExpired', phase: 'search', outcome: null };
    assert.deepEqual(titles({ ...ended, queryIndex: 4 }), [['done', both.slice(0, 1)], ['unconfirmed', both.slice(1)]]);
    assert.deepEqual(titles({ ...ended, queryIndex: 3 }), [['unconfirmed', both]]);
    assert.deepEqual(steps(live, { ...planned, ...ended, queryIndex: 3 }).slice(0, 3).map(step => step[1]), ['done', 'done', 'done']);
});

test('in a plan without Track-title searches, a search the candidate bound kept unsent is skipped, and never done once MusicBrainz\'s retries run out after the searches', () => {
    // Generic member titles plan no Track-title search, so the title searches may fill the bound of 25: the first search's 25
    // releases leave the search by the name alone unsent while release details run.
    const doc = reviewLookupDocument({ title: 'Synthetic Popular Album', primaryNames: ['Synthetic Artist'], members: [{ durationMs: 215_659, title: 'Intro' },
        { durationMs: 382_752, title: 'Outro' }] });
    const first = begin(doc), found = Array.from({ length: 25 }, (_entry, index) => ({ releaseId: syntheticMbid(300 + index), trackCount: 2 }));
    let ran = proceedLookupRun(first.next, doc, { kind: 'found', action: first.step.action!, found, complete: false } as never, stepped), record = ran.next;
    assert.deepEqual([record.phase, record.queryIndex, record.candidates.length, record.searchComplete], ['details', 1, 25, false]);
    const credited = ['albumArtist', 'done', ['Synthetic Popular Album · Synthetic Artist']], none = ['trackTitle', 'skipped', []];
    assert.deepEqual(rows(record, doc).slice(0, 3), [credited, ['album', 'skipped', ['Synthetic Popular Album']], none]);
    // MusicBrainz fails the details until its retries run out: `queryIndex` moves past the plan and the iTunes stage starts, yet
    // the search never sent stays unconfirmed, while that stage runs and once the run completes from it.
    for (let attempt = 1; attempt <= 4; attempt++) {
        const at = new Date(stepped.getTime() + attempt * 1_000);
        ran = proceedLookupRun(record, doc, { kind: 'failed', source: 'musicbrainz', failure: 'unavailable', retryAfterMs: null } as never, at);
        if (ran.next.state === 'retrying') ran = proceedLookupRun({ ...ran.next, state: 'running' }, doc, null, at);
        record = ran.next;
    }
    assert.deepEqual([record.state, record.phase, record.queryIndex], ['running', 'itunes', 2]);
    const unsent = [credited, ['album', 'unconfirmed', ['Synthetic Popular Album']], none];
    assert.deepEqual(rows(record, doc).slice(0, 3), unsent);
    // No storefront has the Album, so its iTunes requests settle and the run completes.
    for (let request = 0; request < 10 && ran.step.action?.kind === 'itunes'; request++) {
        ran = proceedLookupRun(ran.next, doc, { kind: 'itunes', action: ran.step.action, result: null } as never, stepped);
    }
    record = ran.next;
    assert.deepEqual([record.state, record.issue, record.queryIndex], ['complete', 'sourceUnavailable', 2]);
    assert.deepEqual(rows(record, doc).slice(0, 3), unsent);
    // Of the title searches only the first is done with its text.
    const done = catalogReviewLookupView(record, doc, { timeline: true })!.timeline!.steps.filter(step => step.state === 'done' && step.texts?.length);
    assert.deepEqual(done.map(step => step.kind), ['albumArtist']);
});

test('a bridge search names its title only once answered: one left unsent when MusicBrainz\'s retries ran out checked nothing', () => {
    const doc = candy(), { input, plan } = candyPlan(doc);
    const bridge = (bridgeOutcomes: string[]) => steps(doc, { input, queries: plan.queries, queryIndex: 5, trackTitleSearch: 'sent', creditFound: true,
        candidates: [fetched(3, '創生'), fetched(4, '色彩')], itunesStage: stage({ bridge: [bridgeQuery('創生'), bridgeQuery('色彩')], bridgeIndex: 2, bridgeOutcomes }) })
        .find(step => step[0] === 'bridge')!.slice(2);
    assert.deepEqual(bridge(['found', 'unsent']), ['2/2', ['創生']]);
    assert.deepEqual(bridge(['none', 'found']), ['2/2', ['創生', '色彩']]);
    assert.deepEqual(bridge(['refused', 'unsent']), ['2/2', []]);
});

test('a retrying review run shows when it retries, for which source and which retry of how many; any other run, an unreadable time or an attempt out of bounds shows none', () => {
    const doc = candy(), { input, plan } = candyPlan(doc), at = new Date('2026-10-22T01:26:10Z');
    const retrying = (extra: Record<string, unknown>) => timeline(doc, { input, queries: plan.queries, queryIndex: 3, state: 'retrying', issue: 'sourceBusy', phase: 'details',
        retryAt: at, attempts: { musicbrainz: 2 }, outcome: null, completedAt: null, ...extra })!.retry;
    assert.deepEqual(retrying({}), { at: at.toISOString(), source: 'musicbrainz', attempt: 2, limit: 3 });
    assert.deepEqual(retrying({ phase: 'itunes', issue: 'sourceUnavailable', attempts: { musicbrainz: 3, itunes: 1 }, itunesStage: stage({ requestIndex: 0, state: 'running' }) }),
        { at: at.toISOString(), source: 'itunes', attempt: 1, limit: 3 });
    // A bridge search goes to MusicBrainz.
    assert.equal(retrying({ phase: 'bridge', itunesStage: stage({ bridgeIndex: 1, state: 'running' }) })!.source, 'musicbrainz');
    for (const extra of [{ attempts: { musicbrainz: 0 } }, { attempts: { musicbrainz: 4 } }, { attempts: { musicbrainz: 1.5 } }, { attempts: null }, { phase: 'itunes', attempts: { musicbrainz: 2 } },
        { retryAt: null }, { retryAt: new Date(Number.NaN) }, { retryAt: '2026-10-22T01:26:10Z' }, { retryAt: new Date('+010000-01-01T00:00:00Z') }, { state: 'running' }, { state: 'complete' }])
        assert.equal(retrying(extra), null, JSON.stringify(extra));
});

test('a timeline\'s times are the run\'s start, last step and end within the years 0000-9999; an unreadable start or last-step time, a run that planned no search or a view not built for the lookup read leaves the key out, and an import view never carries it', () => {
    const doc = candy(), searched = { queries: candyPlan(doc).plan.queries.slice(0, 1), queryIndex: 1 };
    assert.deepEqual(['startedAt', 'updatedAt', 'completedAt'].map(key => timeline(doc, searched)![key as 'startedAt']), [started.toISOString(), stepped.toISOString(), stepped.toISOString()]);
    for (const completedAt of [null, undefined, new Date(Number.NaN), '2026-10-22T01:25:14.027Z', new Date('+010000-01-01T00:00:00Z')])
        assert.equal(timeline(doc, { ...searched, completedAt })!.completedAt, null, String(completedAt));
    for (const extra of [{ createdAt: undefined }, { createdAt: new Date(Number.NaN) }, { updatedAt: '2026-10-22T01:25:14.027Z' }, { createdAt: new Date('-000001-01-01T00:00:00Z') },
        { updatedAt: new Date('+010000-01-01T00:00:00Z') }]) {
        const view = catalogReviewLookupView(run(doc, { ...searched, ...extra }), doc, { timeline: true })!;
        assert.equal('timeline' in view, false, JSON.stringify(extra));
    }
    // A run with nothing to search (no saved title) completed at once and has no steps; its status says why.
    assert.equal(timeline(doc, { queries: [], queryIndex: 0, outcome: 'noQuery', candidates: [] }), undefined);
    // Only the lookup read builds the timeline; a view built for a brief carries none.
    assert.equal('timeline' in catalogReviewLookupView(run(doc, searched), doc)!, false);
    const imported = { ...run(doc), input: { trigger: 'submitted', submitted: { kind: 'album', text: 'CANDY LIVE 2' } } } as MetadataLookupRecord;
    assert.equal('timeline' in (importLookupView(imported, doc)! as object), false);
});

test('a review candidate\'s subset comparison shows how its pairing was made single only when stored on a single pairing; unknown values and other pairings show none, and the import view never carries it', () => {
    const doc = reviewLookupDocument({ members: [{ durationMs: 215_640, title: '1-01 Synthetic One' }, { durationMs: 382_746, title: '1-02 Synthetic Two' }] });
    const candidates: StoredLookupCandidate[] = [fetched(1, 'Synthetic Album')];
    const ranked = rankLookupWithinBudget(candidates, doc, stepped, { searchComplete: true, exactSearchComplete: true });
    const withSubset = (change: (subset: Record<string, unknown>) => void) => {
        const ranking = structuredClone(ranked.ranking) as unknown as { candidates: { comparison: { subset: Record<string, unknown> } }[] };
        change(ranking.candidates[0].comparison.subset);
        return catalogReviewLookupView(run(doc, { candidates: ranked.candidates, ranking }), doc)!.candidates[0].comparison!.subset!;
    };
    for (const pairedBy of ['titlePositions', 'fileNamePositions', 'nearExactDuration'])
        assert.equal(withSubset(subset => { subset.pairing = 'unique'; subset.pairedBy = pairedBy; }).pairedBy, pairedBy);
    for (const change of [(subset: Record<string, unknown>) => { subset.pairing = 'unique'; delete subset.pairedBy; }, (subset: Record<string, unknown>) => { subset.pairing = 'unique'; subset.pairedBy = 'guess'; },
        (subset: Record<string, unknown>) => { subset.pairing = 'ambiguous'; subset.pairs = []; subset.pairedBy = 'titlePositions'; }]) assert.equal('pairedBy' in withSubset(change), false);
    const imported = { ...run(doc, { candidates: ranked.candidates, ranking: ranked.ranking }), input: { trigger: 'submitted', submitted: { kind: 'album', text: 'Synthetic Album' } } } as MetadataLookupRecord;
    assert.equal(JSON.stringify(importLookupView(imported, doc)).includes('pairedBy'), false);
});

test('the timeline stays within its bounds: at most six title searches, four texts a step, counts within 100 and twelve steps', () => {
    const doc = candy(), { input, plan } = candyPlan(doc), title = plan.queries[1];
    const shown = timeline(doc, { input, queries: [...Array.from({ length: 150 }, () => title), ...plan.queries.slice(3)], queryIndex: 200, trackTitleSearch: 'sent', creditFound: true,
        candidates: Array.from({ length: 130 }, (_entry, index) => fetched(100 + index, '創生')), itunesStage: stage({ bridge: Array.from({ length: 4 }, (_entry, index) => bridgeQuery(['創生', '色彩'][index % 2])) }),
        aliases: Array.from({ length: 130 }, (_entry, index) => alias(index, index < 104 ? 'fetched' : 'pending')) })!;
    assert.equal(shown.steps.filter(step => step.kind === 'album').length, 6);
    assert.ok(shown.steps.length <= 12);
    for (const step of shown.steps) {
        assert.ok((step.texts?.length ?? 1) >= 1 && (step.texts?.length ?? 0) <= 4, step.kind);
        if (step.total !== undefined) assert.ok(Number.isInteger(step.done) && step.done! <= step.total && step.total <= 100, step.kind);
    }
    assert.deepEqual(shown.steps.filter(step => step.kind === 'details' || step.kind === 'aliases').map(step => [step.done, step.total]), [[100, 100], [100, 100]]);
    // A bridge title is listed once, and the second one is no shown candidate's title.
    assert.deepEqual(shown.steps.find(step => step.kind === 'bridge')!.texts, [{ text: '創生' }]);
    // A text over 200 characters is never shown, even when it is the review's own.
    const long = reviewLookupDocument({ title: 'S'.repeat(201) }), longPlan = planCatalogReviewLookup(long);
    assert.equal(timeline(long, { input: longPlan.input, queries: [{ kind: 'musicBrainzReleaseSearch', query: { release: 'S'.repeat(201) }, basis: 'albumText' }], queryIndex: 1 })!.steps[0].texts, undefined);
});
